   "degisiklikTablosu": ["4857 SAYILI KANUNA EK VE DEĞİŞİKLİK GETİREN MEVZUATIN", "YÜRÜRLÜĞE GİRİŞ TARİHLERİNİ GÖSTERİR LİSTE", "Kanun/KHK", "No.", "Kanun/KHK", "Resmî Gazete Tarihi", "Kanun/KHK Yürürlüğe Giriş Tarihi", "Anayasa Mahkemesi Kararı Tarih/ No.", "4857 Sayılı Kanunun Değiştirilen Maddeleri", "1.", "4884", "17/6/2003", "17/6/2003", "-", "3", "2.", "5378", "7/7/2005", "7/7/2005", "-", "108", "3.", "5538", "12/7/2006", "12/7/2006", "-", "2, 81", "4.", "5728", "8/2/2008", "8/2/2008", "-", "107, 108", "5.", "5754", "8/5/2008", "8/5/2008", "-", "32, 102", "6.", "5763", "26/5/2008", "26/5/2008", "-", "3, 33, 65, 78, 81, 82, 88, 95, 98, 105, 108, 111", "7.", "5763", "26/5/2008", "1/7/2008", "-", "30", "8.", "5763", "26/5/2008", "1/1/2009", "-", "85", "9.", "5797", "19/8/2008", "1/7/2008 tarihinden geçerli olmak üzere yayımı tarihinde", "-", "30", "10.", "5838", "28/2/2009", "(Mükerrer)", "28/2/2009", "-", "18", "11.", "6009", "1/8/2010", "1/8/2010", "-", "2, 81", "12.", "6111", "25/2/2011", "(1. Mükerrer)", "25/2/2011", "-", "74, 91, 92, 108", "13.", "KHK/665", "2/11/2011", "(Mükerrer)", "2/11/2011", "-", "30", "14.", "6270", "26/1/2012", "26/1/2012", "-", "99, 100, 101, 102, 103, 104, 105", "15.", "6353", "12/7/2012", "12/7/2012", "-", "30", "16.", "6331", "30/6/2012", "30/12/2012", "-", "2, 4, 7, 25, 63, 69, 71, 77, 78, 79, 80, 81, 83, 84, 85, 86,87, 88, 89, 95, 98, 105, Geçici Madde 2", "17.", "6462", "3/5/2013", "3/5/2013", "-", "25, 30, 101", "18.", "6518", "6/2/2014", "19/2/2014", "-", "5, 30, Ek Madde 1", "4857 SAYILI KANUNA EK VE DEĞİŞİKLİK GETİREN MEVZUATIN", "YÜRÜRLÜĞE GİRİŞ TARİHLERİNİ GÖSTERİR TABLO", "Değiştiren Kanunun/ KHK’nin veya İptal Eden Anayasa Mahkemesi Kararının Numarası", "4857 Sayılı Kanunun Değişen veya İptal Edilen Maddeleri", "Yürürlüğe Giriş Tarihi", "6552", "3, 18, 36, 41, 53, 56, 112", "11/9/2014", "41inci maddesinin onuncu fıkrası, 63", "1/1/2015", "6645", "41, 46, 55, 63, 69, 71, 104, 112, Ek Madde 2", "23/4/2015", "6663", "13, 74", "10/2/2016", "6704", "56", "26/4/2016", "6715", "7, 14, 63, 99, Geçici Madde 7", "20/5/2016", "7036", "91, 92, Ek Madde 3,", "Geçici Madde 8", "25/10/2017", "20, 21", "1/1/2018", "KHK/700", "2, 36, 39, 43, 54, 55, 92", "24/6/2018 tarihinde birlikte yapılan Türkiye Büyük Millet Meclisi ve Cumhurbaşkanlığı seçimleri sonucunda Cumhurbaşkanının andiçerek göreve başladığı tarihte (9/7/2018)", "7166", "112, Geçici Madde 9", "22/2/2019", "Anayasa Mahkemesinin 19/9/2019 tarihli ve E.:2019/42, K.:2019/73 sayılı Kararı", "112, Geçici Madde 9", "15/10/2019", "7226", "64", "26/3/2020", "7244", "Geçici Madde 10", "17/4/2020", "7252", "Geçici Madde 10,", "Geçici Madde 11", "28/7/2020", "7429", "69", "28/12/2022", "Anayasa Mahkemesinin 8/11/2023 tarihli ve E.: 2020/75; K.: 2023/188 sayılı Kararı", "Geçici Madde 11", "23/1/2024", "7553", "46, 108", "14/7/2025", "7555", "109", "24/7/2025", "7573", "Geçici Madde 12", "29/1/2026", "7578", "74, Ek Madde 2", "1/5/2026"]
